#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
int main() { int n; cin >> n; vector<long long> tails; while (n--) { long long value; cin >> value; auto it = lower_bound(tails.begin(), tails.end(), value); if (it == tails.end()) tails.push_back(value); else *it = value; } cout << tails.size() << '\n'; }
